package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Pedido;

import java.math.BigDecimal;

/**
 * Uma opcao de entrega da loja.
 *
 * Para adicionar uma transportadora nova basta criar uma classe com @Component
 * implementando esta interface: ela entra sozinha no catalogo, sem mexer no
 * calculo do resumo.
 */
public interface ModalidadeEntrega {

    /** Codigo enviado pelo site, em maiusculas (ex.: "EXPRESSA"). */
    String codigo();

    /** Prazo em dias corridos informado no resumo. */
    int prazoEntregaDias();

    /** Valor do frete, ja em centavos. */
    BigDecimal frete(Pedido pedido);

    /** Limitacoes da modalidade (ex.: motoboy leva no maximo 5 kg). */
    default boolean atende(Pedido pedido) {
        return true;
    }
}
EOF

cat > entrega/FretePorPeso.java <<'EOF'
package com.loja.checkout.entrega;

import com.loja.checkout.dominio.Dinheiro;
import com.loja.checkout.dominio.Pedido;

import java.math.BigDecimal;

/** Base para transportadoras que cobram um valor fixo mais um tanto por quilo. */
public abstract class FretePorPeso implements ModalidadeEntrega {

    private final BigDecimal valorFixo;
    private final BigDecimal valorPorKg;

    protected FretePorPeso(String valorFixo, String valorPorKg) {
        this.valorFixo = new BigDecimal(valorFixo);
        this.valorPorKg = new BigDecimal(valorPorKg);
    }

    @Override
    public BigDecimal frete(Pedido pedido) {
        return Dinheiro.centavos(valorFixo.add(valorPorKg.multiply(pedido.pesoKg())));
    }
}
EOF

