        // exatamente R$ 1.000,00 ainda passa
        assertThat(calcular(List.of(item("Casaco", "500.00", 2, "0.50")),
                "RETIRADA_LOJA", null, "BOLETO", 1).totalFinal()).isEqualByComparingTo("1003.49");
    }

