        // modalidade invalida ganha do cupom invalido
        esperaErro(ErroCheckout.MODALIDADE_INVALIDA,
                List.of(camiseta()), "DRONE", "NATAL2020", "DINHEIRO", 9);
        // modalidade indisponivel ganha do cupom invalido
